auth.mail.invite.text:
.input {$days :number}
.match $days
one {{You are invited to join {$organization} (role {$role}).
Single-use link, valid for {$days} day:
{$url}}}
* {{You are invited to join {$organization} (role {$role}).
Single-use link, valid for {$days} days:
{$url}}}

auth.mail.magic.text:
.input {$minutes :number}
.match $minutes
one {{To sign in, open this link (valid for {$minutes} minute, single use):
{$url}}}
* {{To sign in, open this link (valid for {$minutes} minutes, single use):
{$url}}}

auth.mail.reset.text:
.input {$hours :number}
.match $hours
one {{To choose a new password, open this link (valid for {$hours} hour):
{$url}}}
* {{To choose a new password, open this link (valid for {$hours} hours):
{$url}}}
